import subprocess
import ftplib
import os

def task_func(ftp_server='ftp.dlptest.com', ftp_user='dlpuser', ftp_password='rNrKYTX9g7z3RgJRmxWuGHbeu', ftp_dir='/ftp/test'):
    ftp = None
    try:
        try:
            ftp = ftplib.FTP(ftp_server)
        except Exception as e:
            raise Exception(f"Failed to connect to FTP server {ftp_server}: {str(e)}")

        try:
            ftp.login(user=ftp_user, passwd=ftp_password)
        except Exception as e:
            raise Exception(f"Failed to log into FTP server {ftp_server} with user {ftp_user}: {str(e)}")

        try:
            ftp.cwd(ftp_dir)
        except Exception as e:
            raise Exception(f"Failed to change to directory {ftp_dir} on server {ftp_server}: {str(e)}")

        try:
            filenames = ftp.nlst()
        except Exception:
            filenames = []

        attempted_downloads = []

        for filename in filenames:
            if filename in ("", ".", ".."):
                continue

            base_name = filename.split('/')[-1]
            if not base_name or base_name in (".", ".."):
                continue

            attempted_downloads.append(base_name)

            stripped_dir = ftp_dir.strip('/')
            if stripped_dir:
                ftp_url = f"ftp://{ftp_server}/{stripped_dir}/{base_name}"
            else:
                ftp_url = f"ftp://{ftp_server}/{base_name}"

            cmd = [
                "wget",
                "--user", ftp_user,
                "--password", ftp_password,
                ftp_url
            ]
            try:
                subprocess.run(cmd, check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            except Exception:
                pass

        return attempted_downloads
    finally:
        if ftp is not None:
            try:
                ftp.quit()
            except Exception:
                try:
                    ftp.close()
                except Exception:
                    pass

import subprocess
import psutil
import time

def task_func(process_name: str) -> str:
    found = False
    for p in psutil.process_iter():
        try:
            if p.name() == process_name:
                found = True
                p.terminate()
        except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
            pass

    subprocess.Popen(process_name)

    if found:
        return f"Process found. Restarting {process_name}."
    else:
        return f"Process not found. Starting {process_name}."

from flask import Flask, render_template, redirect, url_for
from flask_login import LoginManager, UserMixin, login_user, login_required, logout_user, current_user
from flask_wtf import FlaskForm
from wtforms import StringField, PasswordField, SubmitField
from wtforms.validators import DataRequired, Length
from werkzeug.security import generate_password_hash, check_password_hash

class LoginForm(FlaskForm):
    username = StringField('Username', validators=[DataRequired(), Length(min=4, max=25)])
    password = PasswordField('Password', validators=[DataRequired(), Length(min=8, max=80)])
    submit = SubmitField('Log In')

login_manager = LoginManager()

def task_func(secret_key, template_folder):
    app = Flask(__name__, template_folder=template_folder)
    app.config['SECRET_KEY'] = secret_key

    login_manager.init_app(app)
    login_manager.login_view = 'login'

    class User(UserMixin):
        def __init__(self, user_id):
            self.id = str(user_id)

    @login_manager.user_loader
    def load_user(user_id):
        return User(user_id)

    @app.route('/login', methods=['GET', 'POST'])
    def login():
        form = LoginForm()
        if form.validate_on_submit():
            user = User(form.username.data)
            login_user(user)
            return redirect(url_for('protected'))
        return render_template('login.html', form=form)

    @app.route('/protected')
    @login_required
    def protected():
        return f'Logged in as: {current_user.id}'

    @app.route('/logout')
    @login_required
    def logout():
        logout_user()
        return redirect(url_for('login'))

    return app

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from sklearn.decomposition import PCA

def task_func(data, n_components=2):
    if isinstance(n_components, bool) or not isinstance(n_components, int) or n_components <= 0:
        raise ValueError("n_components must be a positive integer.")

    if isinstance(data, pd.DataFrame):
        df = data.copy()
    else:
        try:
            df = pd.DataFrame(data)
        except Exception:
            try:
                df = pd.DataFrame([data])
            except Exception:
                raise ValueError("All input data must be numeric.")

    if df.empty:
        transformed_df = pd.DataFrame(columns=[f"PC{i+1}" for i in range(n_components)])
        fig, ax = plt.subplots()
        return transformed_df, ax

    numeric_df = df.select_dtypes(include=[np.number])
    if numeric_df.shape[1] != df.shape[1]:
        raise ValueError("All input data must be numeric.")

    if numeric_df.shape[0] == 0 or numeric_df.shape[1] == 0:
        transformed_df = pd.DataFrame(columns=[f"PC{i+1}" for i in range(n_components)])
        fig, ax = plt.subplots()
        return transformed_df, ax

    max_components = min(numeric_df.shape[0], numeric_df.shape[1])
    if n_components > max_components:
        raise ValueError("n_components cannot exceed min(n_samples, n_features).")

    pca = PCA(n_components=n_components)
    transformed = pca.fit_transform(numeric_df.values)
    transformed_df = pd.DataFrame(
        transformed,
        columns=[f"PC{i+1}" for i in range(n_components)],
        index=numeric_df.index
    )

    fig, ax = plt.subplots()
    if n_components == 1:
        ax.scatter(transformed_df.iloc[:, 0], np.zeros(len(transformed_df)))
        ax.set_xlabel("PC1")
        ax.set_ylabel("Value")
    else:
        ax.scatter(transformed_df.iloc[:, 0], transformed_df.iloc[:, 1])
        ax.set_xlabel("PC1")
        ax.set_ylabel("PC2")
    ax.set_title("PCA Transformed Data")

    return transformed_df, ax
